/**
 * Pure game/room logic for the D&D turn tracker.
 *
 * This file runs both in Node.js (server mode) and in the browser (when a
 * tablet/phone hosts the room itself), so it has no dependencies.
 *
 * Rooms are plain JSON objects so they can be persisted as-is.
 * Every mutating function takes the requesting client's secret `clientId`
 * and throws a GameError when the request is invalid or not allowed.
 *
 * Identity model:
 *  - `clientId` is a secret random id generated by each browser and kept in
 *    localStorage. It is NEVER sent to other clients.
 *  - each member also gets a public `id` that is safe to share.
 *  - enemies have no owner: whoever is currently the DM controls them.
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.DndRooms = factory();
})(typeof self !== 'undefined' ? self : this, function () {
'use strict';

function randomBytes(n) {
  const out = new Uint8Array(n);
  const c = typeof globalThis !== 'undefined' && globalThis.crypto && globalThis.crypto.getRandomValues
    ? globalThis.crypto
    : require('crypto').webcrypto;
  c.getRandomValues(out);
  return out;
}

const CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O, 1/I
const CODE_LENGTH = 5;

/** "Practically unlimited" cap for numbers (HP, level, AC, bar max…). */
const BIG = 1000000;

const LIMITS = {
  name: 40,
  cls: 40,
  statKey: 40,
  statValue: 200,
  stats: 100,
  conditions: 24,
  combatants: 300,
  enemyBatch: 50,
  log: 60,
  members: 30,
  companions: 3, // friendly NPCs per player
};

const TYPES = ['pc', 'companion', 'enemy'];

class GameError extends Error {}

function randomId(bytes = 9) {
  return Array.from(randomBytes(bytes), (b) => b.toString(16).padStart(2, '0')).join('');
}

function randomCode(length = CODE_LENGTH) {
  let out = '';
  const bytes = randomBytes(length);
  for (let i = 0; i < length; i++) out += CODE_ALPHABET[bytes[i] % CODE_ALPHABET.length];
  return out;
}

function normalizeCode(code) {
  return String(code ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 12);
}

/* ------------------------------------------------------------------ */
/* Input sanitizing                                                    */
/* ------------------------------------------------------------------ */

function str(value, max) {
  return String(value ?? '')
    .replace(/[\u0000-\u001f\u007f]/g, ' ')
    .trim()
    .slice(0, max);
}

function int(value, min, max, fallback) {
  const n = Number.parseInt(value, 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

function initiativeValue(value, fallback = 0) {
  const n = Number.parseFloat(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.round(Math.min(9999, Math.max(-999, n)) * 100) / 100;
}

const BAR_COLORS = ['blue', 'purple', 'yellow', 'orange', 'teal', 'pink', 'gray'];

/** Pick a sensible default bar color from the stat's name. */
function defaultBarColor(key) {
  const k = key.toLowerCase();
  if (/mana|spell|slot|magic|ki|sorcery|arcan/.test(k)) return 'blue';
  if (/move|movement|speed|stamina|feet|ft/.test(k)) return 'yellow';
  if (/rage|fury|superiority|action surge/.test(k)) return 'orange';
  if (/shield|temp|ward/.test(k)) return 'teal';
  return 'purple';
}

function isBlank(v) {
  return v === undefined || v === null || String(v).trim() === '';
}

/**
 * Custom stats. A stat with a `max` is shown as a bar (e.g. Mana 12/20,
 * Movement 30/30); otherwise it's a text chip (e.g. Spell DC 15).
 * Bars can refill automatically at the start of their creature's turn.
 */
function cleanStats(stats) {
  if (!Array.isArray(stats)) return [];
  const out = [];
  for (const s of stats) {
    if (!s || typeof s !== 'object') continue;
    const key = str(s.key, LIMITS.statKey);
    if (!isBlank(s.max)) {
      const max = int(s.max, 1, BIG, 0);
      if (max > 0) {
        const value = isBlank(s.value) ? max : int(s.value, 0, max, max);
        const color = BAR_COLORS.includes(s.color) ? s.color : defaultBarColor(key);
        out.push({ key: key || 'Resource', value, max, color, refill: Boolean(s.refill) });
        if (out.length >= LIMITS.stats) break;
        continue;
      }
    }
    const value = str(s.value, LIMITS.statValue);
    if (!key && !value) continue;
    out.push({ key: key || 'Stat', value });
    if (out.length >= LIMITS.stats) break;
  }
  return out;
}

const isBar = (s) => typeof s.max === 'number';

/* ------------------------------------------------------------------ */
/* Conditions: buffs & debuffs                                         */
/* ------------------------------------------------------------------ */

/** Colors a condition can paint a bar with. */
const TINTS = ['green', 'red', 'orange', 'yellow', 'blue', 'cyan', 'purple', 'pink', 'gray'];
const CONDITION_KINDS = ['buff', 'debuff', 'neutral'];
/** Which bar a condition recolors: hp, magic bars, movement bars, all bars, or one named bar ("stat:Ki"). */
const BAR_TARGETS = ['hp', 'mana', 'move', 'all'];

/**
 * Ready-made conditions. `official` = the conditions from the D&D 5e rules
 * (SRD); the rest are common spell/class effects. Durations are in rounds.
 */
const CONDITION_PRESETS = [
  { key: 'blinded', name: 'Blinded', emoji: '🙈', kind: 'debuff', official: true },
  { key: 'charmed', name: 'Charmed', emoji: '💖', kind: 'debuff', official: true },
  { key: 'deafened', name: 'Deafened', emoji: '🙉', kind: 'debuff', official: true },
  { key: 'exhaustion', name: 'Exhaustion', emoji: '🥱', kind: 'debuff', official: true, levels: 6 },
  { key: 'frightened', name: 'Frightened', emoji: '😱', kind: 'debuff', official: true },
  { key: 'grappled', name: 'Grappled', emoji: '🤼', kind: 'debuff', official: true, color: 'gray', bar: 'move' },
  { key: 'incapacitated', name: 'Incapacitated', emoji: '💫', kind: 'debuff', official: true },
  { key: 'invisible', name: 'Invisible', emoji: '👻', kind: 'buff', official: true },
  { key: 'paralyzed', name: 'Paralyzed', emoji: '⚡', kind: 'debuff', official: true, color: 'yellow', bar: 'move' },
  { key: 'petrified', name: 'Petrified', emoji: '🗿', kind: 'debuff', official: true, color: 'gray', bar: 'all' },
  { key: 'poisoned', name: 'Poisoned', emoji: '🤢', kind: 'debuff', official: true, color: 'purple', bar: 'hp' },
  { key: 'prone', name: 'Prone', emoji: '🛌', kind: 'debuff', official: true },
  { key: 'restrained', name: 'Restrained', emoji: '⛓️', kind: 'debuff', official: true, color: 'gray', bar: 'move' },
  { key: 'stunned', name: 'Stunned', emoji: '😵', kind: 'debuff', official: true },
  { key: 'unconscious', name: 'Unconscious', emoji: '💤', kind: 'debuff', official: true, color: 'gray', bar: 'hp' },
  { key: 'blessed', name: 'Blessed', emoji: '✨', kind: 'buff', color: 'yellow', bar: 'hp', rounds: 10 },
  { key: 'hasted', name: 'Hasted', emoji: '🏃', kind: 'buff', color: 'cyan', bar: 'move', rounds: 10 },
  { key: 'raging', name: 'Raging', emoji: '😡', kind: 'buff', color: 'orange', bar: 'hp', rounds: 10 },
  { key: 'concentrating', name: 'Concentrating', emoji: '🧠', kind: 'neutral', color: 'blue', bar: 'mana' },
  { key: 'inspired', name: 'Inspired', emoji: '🎵', kind: 'buff' },
  { key: 'dodging', name: 'Dodging', emoji: '🛡️', kind: 'buff', rounds: 1 },
  { key: 'hidden', name: 'Hidden', emoji: '🥷', kind: 'buff' },
  { key: 'regenerating', name: 'Regenerating', emoji: '💚', kind: 'buff', color: 'cyan', bar: 'hp' },
  { key: 'slowed', name: 'Slowed', emoji: '🐌', kind: 'debuff', color: 'gray', bar: 'move', rounds: 10 },
  { key: 'burning', name: 'Burning', emoji: '🔥', kind: 'debuff', color: 'orange', bar: 'hp' },
  { key: 'bleeding', name: 'Bleeding', emoji: '🩸', kind: 'debuff', color: 'red', bar: 'hp' },
  { key: 'cursed', name: 'Cursed', emoji: '🧿', kind: 'debuff', color: 'pink', bar: 'all' },
];

function cleanBarTarget(bar) {
  const b = String(bar ?? '');
  if (BAR_TARGETS.includes(b)) return b;
  if (b.startsWith('stat:')) {
    const k = str(b.slice(5), LIMITS.statKey);
    return k ? `stat:${k}` : '';
  }
  return '';
}

/** Build a clean condition from a preset key or custom fields. */
function cleanCondition(input, isDm) {
  if (!input || typeof input !== 'object') throw new GameError('Invalid condition.');
  const preset = input.preset ? CONDITION_PRESETS.find((p) => p.key === input.preset) : null;
  if (input.preset && !preset) throw new GameError('Unknown condition.');
  const src = preset ? { ...preset, rounds: isBlank(input.rounds) ? preset.rounds : input.rounds } : input;
  const name = str(src.name, 24);
  if (!name) throw new GameError('Give the condition a name.');
  const kind = CONDITION_KINDS.includes(src.kind) ? src.kind : 'neutral';
  const emoji = str(src.emoji, 16) || (kind === 'buff' ? '⬆️' : kind === 'debuff' ? '⬇️' : '🔹');
  const color = TINTS.includes(src.color) ? src.color : '';
  return {
    key: preset ? preset.key : null,
    name,
    emoji,
    kind,
    color,
    bar: color ? cleanBarTarget(src.bar) : '',
    rounds: isBlank(src.rounds) ? null : int(src.rounds, 1, 9999, null),
    level: preset && preset.levels ? int(input.level, 1, preset.levels, 1) : null,
    secret: Boolean(isDm && input.secret),
  };
}

function cleanName(name) {
  const n = str(name, 30);
  if (!n) throw new GameError('Please enter your name.');
  return n;
}

/* ------------------------------------------------------------------ */
/* Room lifecycle                                                      */
/* ------------------------------------------------------------------ */

/**
 * Create a room. The creator is the DM, unless `opts.screen` is set: then the
 * creating device is a shared "table screen" (it hosts and shows the fight
 * but cannot act), and the DM joins from their own phone with the DM key.
 */
function createRoom(existingCodes, clientId, playerName, opts = {}) {
  if (!clientId) throw new GameError('Missing client id.');
  const name = cleanName(playerName);
  let code;
  do code = randomCode(); while (existingCodes.has(code));

  const now = Date.now();
  const room = {
    code,
    createdAt: now,
    updatedAt: now,
    dmKey: randomCode(6),
    members: {},
    combatants: [],
    nextOrder: 1,
    combat: { active: false, round: 0, turnId: null, cursor: null, seq: 0, phase: null, queue: [] },
    lastOrder: [],
    map: { url: '', kind: 'page', strokes: [] },
    settings: { revealEnemies: false },
    log: [],
  };
  if (opts.screen) {
    room.members[clientId] = { id: randomId(), name, role: 'screen', creator: true, joinedAt: now };
    addLog(room, `${name} (table screen) created the room. The DM joins with the DM key.`);
  } else {
    room.members[clientId] = { id: randomId(), name, role: 'dm', joinedAt: now };
    addLog(room, `${name} created the room and is the Dungeon Master.`);
  }
  return room;
}

/**
 * Join (or re-join) a room. A known clientId keeps its role.
 * Passing the room's DM key makes the caller the DM (the previous DM
 * becomes a regular player). `opts.screen` joins a new device as a
 * table display (view only).
 */
function joinRoom(room, clientId, playerName, dmKey, opts = {}) {
  if (!clientId) throw new GameError('Missing client id.');
  const name = cleanName(playerName);
  let member = room.members[clientId];
  const wantsDm = dmKey != null && String(dmKey).trim() !== '';

  if (wantsDm && String(dmKey).trim().toUpperCase() !== room.dmKey) {
    throw new GameError('Wrong DM key.');
  }

  if (!member) {
    if (Object.keys(room.members).length >= LIMITS.members) throw new GameError('This room is full.');
    const screen = Boolean(opts.screen) && !wantsDm;
    member = { id: randomId(), name, role: screen ? 'screen' : 'player', joinedAt: Date.now() };
    room.members[clientId] = member;
    const joined = screen
      ? (/display|screen/i.test(name) ? `📺 ${name} joined.` : `📺 ${name} joined as a table display.`)
      : `${name} joined the room.`;
    addLog(room, joined);
  } else if (member.name !== name) {
    addLog(room, `${member.name} is now called ${name}.`);
    member.name = name;
  }

  if (wantsDm && member.role === 'screen') throw new GameError('The table screen cannot become the DM.');
  if (wantsDm && member.role !== 'dm') {
    for (const m of Object.values(room.members)) if (m.role === 'dm') m.role = 'player';
    member.role = 'dm';
    addLog(room, `${name} is now the Dungeon Master.`);
  }
  touch(room);
  return member;
}

function getMember(room, clientId) {
  const m = room.members[clientId];
  if (!m) throw new GameError('You are not part of this room. Please re-join.');
  return m;
}

function memberById(room, publicId) {
  return Object.values(room.members).find((m) => m.id === publicId) || null;
}

function dmMember(room) {
  return Object.values(room.members).find((m) => m.role === 'dm') || null;
}

function touch(room) {
  room.updatedAt = Date.now();
}

function addLog(room, publicText, dmText) {
  room.log.push({ t: Date.now(), text: publicText, dm: dmText && dmText !== publicText ? dmText : undefined });
  if (room.log.length > LIMITS.log) room.log.splice(0, room.log.length - LIMITS.log);
}

/* ------------------------------------------------------------------ */
/* Combatants                                                          */
/* ------------------------------------------------------------------ */

function findCombatant(room, id) {
  const c = room.combatants.find((x) => x.id === id);
  if (!c) throw new GameError('That creature no longer exists.');
  return c;
}

function canControl(room, member, c) {
  if (member.role === 'dm') return true;
  return c.type !== 'enemy' && c.owner === member.id;
}

function buildFields(input, existing) {
  const hpMax = int(input.hpMax, 1, BIG, existing ? existing.hpMax : 10);
  let hp = int(input.hp, 0, BIG, existing ? existing.hp : hpMax);
  // keep current HP sensible when only max HP changes
  if (input.hp === undefined || input.hp === null || input.hp === '') hp = existing ? Math.min(existing.hp, hpMax) : hpMax;
  hp = Math.min(hp, hpMax);
  return {
    name: str(input.name, LIMITS.name),
    cls: str(input.cls, LIMITS.cls),
    level: int(input.level, 0, BIG, existing ? existing.level : 1),
    hpMax,
    hp,
    ac: int(input.ac, 0, BIG, existing ? existing.ac : 10),
    // Initiative is entered on the main page (setInitiative) as a d20 roll;
    // the total is roll + bonus. A raw `initiative` (e.g. lair actions on 20)
    // is still accepted as a fixed total.
    ...initiativeFields(input, existing),
    stats: cleanStats(input.stats),
  };
}

function initiativeFields(input, existing) {
  const initBonus = int(input.initBonus, -999, 9999, existing ? existing.initBonus || 0 : 0);
  if (!isBlank(input.initiative)) return { initBonus, initRoll: null, initiative: initiativeValue(input.initiative, 0) };
  const initRoll = existing && existing.initRoll != null ? existing.initRoll : null;
  const initiative = initRoll != null ? initRoll + initBonus : existing ? existing.initiative ?? null : null;
  return { initBonus, initRoll, initiative };
}

/**
 * Create or update a combatant. Returns the list of created/updated combatants.
 */
function saveCombatant(room, clientId, input) {
  const member = getMember(room, clientId);
  if (!input || typeof input !== 'object') throw new GameError('Invalid data.');

  // ---- update ----
  if (input.id) {
    const c = findCombatant(room, input.id);
    if (!canControl(room, member, c)) throw new GameError('You cannot edit this creature.');
    const f = buildFields(input, c);
    if (!f.name) throw new GameError('Name is required.');
    const before = c.hp;
    Object.assign(c, f);
    if (c.type === 'enemy') applyEnemyExtras(room, c, input);
    if (c.type === 'enemy' && input.hidden !== undefined) {
      const wasHidden = c.hidden;
      c.hidden = Boolean(input.hidden);
      if (wasHidden && !c.hidden) addLog(room, `${c.name} joined the fight!`);
    }
    if (before > 0 && c.hp === 0 && c.type === 'enemy') {
      addLog(room, `💀 ${c.name} is defeated!`);
      onDefeated(room, c);
    }
    touch(room);
    return [c];
  }

  // ---- create ----
  const type = TYPES.includes(input.type) ? input.type : null;
  if (!type) throw new GameError('Unknown creature type.');
  const f = buildFields(input, null);
  if (!f.name) throw new GameError('Name is required.');

  if (type === 'enemy') {
    if (member.role !== 'dm') throw new GameError('Only the Dungeon Master can add enemies.');
    const count = int(input.count, 1, LIMITS.enemyBatch, 1);
    if (room.combatants.length + count > LIMITS.combatants) throw new GameError('Too many creatures in this room.');
    const created = [];
    for (let i = 0; i < count; i++) {
      const c = {
        id: randomId(),
        type,
        owner: null,
        order: room.nextOrder++,
        hidden: Boolean(input.hidden),
        ...f,
        stats: f.stats.map((s) => ({ ...s })),
        name: count > 1 ? `${f.name} ${i + 1}`.slice(0, LIMITS.name + 3) : f.name,
        conditions: [],
      };
      applyEnemyExtras(room, c, input);
      room.combatants.push(c);
      joinRollQueue(room, member);
      created.push(c);
    }
    const first = created[0];
    let label = count > 1 ? `${count}× ${f.name}` : f.name;
    if (first.lair) label = `🏰 ${label}`;
    else if (first.boss) label = `👑 ${label} (boss)`;
    if (first.leader) label += `, summoned by ${findCombatant(room, first.leader).name},`;
    // hidden creatures are only announced to the DM
    if (input.hidden) addLog(room, '', `The DM prepared ${label} (hidden).`);
    else addLog(room, `${label} joined the fight!`);
    touch(room);
    return created;
  }

  // pc / companion: one character and up to LIMITS.companions friendly NPCs per player
  if (member.role === 'screen') throw new GameError('The table screen only displays the fight.');
  if (member.role === 'dm') throw new GameError('The Dungeon Master controls enemies; players add their own characters.');
  const owned = room.combatants.filter((c) => c.owner === member.id && c.type === type);
  if (type === 'pc' && owned.length) throw new GameError('You already have a character. Edit it instead.');
  if (type === 'companion' && owned.length >= LIMITS.companions) {
    throw new GameError(`Each player can have up to ${LIMITS.companions} friendly NPCs.`);
  }
  if (room.combatants.length >= LIMITS.combatants) throw new GameError('Too many creatures in this room.');
  const c = { id: randomId(), type, owner: member.id, order: room.nextOrder++, hidden: false, ...f, conditions: [], reserve: type === 'companion' && Boolean(input.reserve) };
  room.combatants.push(c);
  joinRollQueue(room, member);
  addLog(room, type === 'pc' ? `${member.name} added the character ${c.name}.` : `${member.name} brought along ${c.name} (friendly NPC${c.reserve ? ', in reserve' : ''}).`);
  touch(room);
  return [c];
}

const LEADER_DEATH_RULES = ['dies', 'flees', 'stays'];

/** true if `ancestorId` is `startId` or one of its leaders (prevents loops). */
function isInLeaderChain(room, ancestorId, startId) {
  let cur = startId;
  for (let i = 0; cur && i < 50; i++) {
    if (cur === ancestorId) return true;
    const x = room.combatants.find((c) => c.id === cur);
    cur = x ? x.leader : null;
  }
  return false;
}

/**
 * Boss / summon / lair settings for enemies (only the DM can save enemies).
 *  - boss: shown in the boss bar at the top of every screen
 *  - leader: the enemy that summoned/commands this one
 *  - onLeaderDeath: what happens when the leader falls (dies | flees | stays)
 *  - followLeader: acts right after its leader in the turn order
 *  - lair: a "Lair actions" turn (initiative 20, loses ties, no HP)
 */
function applyEnemyExtras(room, c, input) {
  if (input.boss !== undefined) c.boss = Boolean(input.boss);
  if (input.lair !== undefined) c.lair = Boolean(input.lair);
  if (input.leader !== undefined) {
    const lid = input.leader ? String(input.leader) : null;
    if (lid) {
      const leader = room.combatants.find((x) => x.id === lid && x.type === 'enemy');
      if (!leader) throw new GameError('The leader no longer exists.');
      if (leader.lair) throw new GameError('Lair actions cannot have summons.');
      if (isInLeaderChain(room, c.id, lid)) throw new GameError('A creature cannot be summoned by itself or its own summons.');
      c.leader = lid;
    } else {
      c.leader = null;
    }
  }
  if (input.onLeaderDeath !== undefined) c.onLeaderDeath = LEADER_DEATH_RULES.includes(input.onLeaderDeath) ? input.onLeaderDeath : 'dies';
  if (input.followLeader !== undefined) c.followLeader = Boolean(input.followLeader);
  if (!c.leader) c.followLeader = false;
  if (c.lair) {
    c.hpMax = 1;
    c.hp = 1;
    c.boss = false;
    c.leader = null;
    c.followLeader = false;
  }
}

/**
 * An enemy just dropped to 0 HP: its summons die with it, flee, or keep
 * fighting, depending on each summon's rule (and so on down the chain).
 */
function onDefeated(room, fallen, seen = new Set()) {
  if (seen.has(fallen.id)) return;
  seen.add(fallen.id);
  for (const m of room.combatants.filter((x) => x.leader === fallen.id)) {
    const rule = m.onLeaderDeath || 'dies';
    if (rule === 'stays') continue;
    const say = (text) => (m.hidden ? addLog(room, '', text) : addLog(room, text));
    if (rule === 'flees') {
      onDefeated(room, m, seen);
      room.combatants = room.combatants.filter((x) => x.id !== m.id);
      say(`🏃 ${m.name} flees as ${fallen.name} falls!`);
    } else if (m.hp > 0) {
      m.hp = 0;
      say(`💀 ${m.name} perishes with ${fallen.name}!`);
      onDefeated(room, m, seen);
    }
  }
  // if the creature whose turn it was fled, pass the turn on
  if (room.combat.active && room.combat.turnId && !room.combatants.some((x) => x.id === room.combat.turnId)) {
    room.combat.turnId = null;
    advance(room, +1);
  }
}

/**
 * Friendly NPCs can wait in reserve: they stay in the party but are skipped
 * in the turn order and the initiative round until they join the battle.
 * Owner or DM. A creature joining a running fight keeps its last initiative,
 * or goes last until its owner enters a roll.
 */
function setReserve(room, clientId, { id, reserve } = {}) {
  const member = getMember(room, clientId);
  const c = findCombatant(room, id);
  if (c.type !== 'companion') throw new GameError('Only friendly NPCs can wait in reserve.');
  if (!canControl(room, member, c)) throw new GameError('Only its owner or the DM can do that.');
  const next = Boolean(reserve);
  if (Boolean(c.reserve) === next) return c;
  c.reserve = next;
  if (next) {
    addLog(room, `💤 ${c.name} stays back in reserve.`);
    if (room.combat.active && room.combat.turnId === c.id) advance(room, +1); // it was its turn: pass it on
    if (room.combat.phase === 'rolling') advanceRollQueue(room);
  } else {
    addLog(room, `⚔️ ${c.name} joins the battle!`);
    if (room.combat.phase === 'rolling') { c.initRoll = null; c.initiative = null; } // roll fresh for this fight
    const owner = memberById(room, c.owner);
    if (owner) joinRollQueue(room, owner);
  }
  touch(room);
  return c;
}

function removeCombatant(room, clientId, id) {
  const member = getMember(room, clientId);
  const c = findCombatant(room, id);
  if (!canControl(room, member, c)) throw new GameError('You cannot remove this creature.');
  const wasCurrent = room.combat.active && room.combat.turnId === c.id;
  room.combatants = room.combatants.filter((x) => x.id !== id);
  for (const x of room.combatants) {
    if (x.leader === id) { x.leader = null; x.followLeader = false; }
  }
  if (!c.hidden) addLog(room, `${c.name} left the fight.`);
  if (wasCurrent) {
    room.combat.turnId = null;
    advance(room, +1);
  }
  if (room.combat.phase === 'rolling') advanceRollQueue(room);
  touch(room);
}

/**
 * Apply damage or healing.
 *  - DM: anything.
 *  - Player: damage enemies or their own creatures; heal any PC / friendly NPC.
 */
function changeHp(room, clientId, { targetId, amount, mode, attackerId } = {}) {
  const member = getMember(room, clientId);
  const target = findCombatant(room, targetId);
  const value = int(amount, 0, BIG, 0);
  if (value <= 0) throw new GameError('Enter an amount greater than 0.');
  if (mode !== 'damage' && mode !== 'heal') throw new GameError('Invalid action.');
  if (member.role === 'screen') throw new GameError('The table screen only displays the fight.');

  if (target.lair) throw new GameError('Lair actions have no HP.');
  const isDm = member.role === 'dm';
  if (!isDm) {
    if (target.hidden) throw new GameError('That creature no longer exists.');
    if (mode === 'damage' && target.type !== 'enemy' && target.owner !== member.id) {
      throw new GameError('You can only damage enemies or your own creatures.');
    }
    if (mode === 'heal' && target.type === 'enemy') throw new GameError('You cannot heal enemies.');
  }

  let attacker = null;
  if (attackerId) {
    attacker = room.combatants.find((x) => x.id === attackerId) || null;
    if (attacker && !canControl(room, member, attacker)) attacker = null;
  }
  const who = attacker ? attacker.name : member.name;

  const before = target.hp;
  if (mode === 'damage') target.hp = Math.max(0, target.hp - value);
  else target.hp = Math.min(target.hpMax, target.hp + value);
  const after = target.hp;

  const secret = target.type === 'enemy' && !room.settings.revealEnemies;
  const nums = ` (${before} → ${after} HP)`;
  if (mode === 'damage') {
    const base = `${who} dealt ${value} damage to ${target.name}`;
    addLog(room, secret ? `${base}.` : `${base}${nums}.`, `${base}${nums}.`);
    if (before > 0 && after === 0) {
      addLog(room, target.type === 'enemy' ? `💀 ${target.name} is defeated!` : `⚠️ ${target.name} drops to 0 HP!`);
      if (target.type === 'enemy') onDefeated(room, target);
    }
  } else {
    const base = `${who} healed ${target.name} for ${value}`;
    addLog(room, secret ? `${base}.` : `${base}${nums}.`, `${base}${nums}.`);
  }
  touch(room);
  return target;
}

/* ------------------------------------------------------------------ */
/* Turn order                                                          */
/* ------------------------------------------------------------------ */

/**
 * Turn-order key: [initiative, tie-breaker]. Summons that "act right after
 * their leader" use the leader's key plus a tiny offset; lair actions lose
 * initiative ties (as in the 5e rules).
 */
function sortKey(room, c, depth = 0) {
  if (c.followLeader && c.leader && depth < 10) {
    const leader = room.combatants.find((x) => x.id === c.leader);
    if (leader) {
      const k = sortKey(room, leader, depth + 1);
      return [k[0], k[1] + (0.5 + c.order / 1e7) / (depth + 1)];
    }
  }
  return [c.initiative ?? -1e9, c.lair ? c.order + 1e9 : c.order];
}

/** Initiative as shown: the leader's for summons that act right after it; null = not rolled yet. */
function shownInitiative(room, c) {
  const k = sortKey(room, c)[0];
  return k <= -1e8 ? null : k;
}

/** negative if a acts before b */
function compareKeys(a, b) {
  if (a[0] !== b[0]) return b[0] - a[0]; // higher initiative first
  return a[1] - b[1]; // then whoever was added first
}

function sortedCombatants(room) {
  return [...room.combatants].sort((a, b) => compareKeys(sortKey(room, a), sortKey(room, b)));
}

/** Creatures that actually get a turn: visible, and enemies must be alive. */
function eligible(room) {
  return sortedCombatants(room).filter((c) => !c.hidden && !c.reserve && !(c.type === 'enemy' && c.hp <= 0));
}

function setCurrent(room, c, { refill = true } = {}) {
  room.combat.turnId = c.id;
  room.combat.cursor = sortKey(room, c);
  room.combat.seq += 1;
  // bars marked "refills every turn" (e.g. movement) fill up when the turn starts
  if (refill) for (const s of c.stats || []) if (isBar(s) && s.refill) s.value = s.max;
}

/**
 * Move the turn pointer forward (+1) or back (-1). Works off a "cursor"
 * (initiative + insertion order of the last current creature), so it keeps
 * working even if the current creature was removed or edited.
 */
function advance(room, dir) {
  const list = eligible(room);
  if (list.length === 0) {
    room.combat.turnId = null;
    room.combat.seq += 1;
    return null;
  }
  const cursor = room.combat.cursor;
  let next = null;
  if (!cursor) {
    next = list[0];
  } else if (dir > 0) {
    next = list.find((c) => compareKeys(sortKey(room, c), cursor) > 0) || null;
    if (!next) {
      next = list[0];
      room.combat.round += 1;
      addLog(room, `— Round ${room.combat.round} —`);
    }
  } else {
    const before = list.filter((c) => compareKeys(sortKey(room, c), cursor) < 0);
    next = before[before.length - 1] || null;
    if (!next) {
      next = list[list.length - 1];
      room.combat.round = Math.max(1, room.combat.round - 1);
    }
  }
  setCurrent(room, next, { refill: dir > 0 });
  return next;
}

function requireDm(member) {
  if (member.role !== 'dm') throw new GameError('Only the Dungeon Master can do that.');
}

/* ------------------------------------------------------------------ */
/* Initiative round                                                    */
/* ------------------------------------------------------------------ */

/** Creatures that roll their own initiative (not lair actions or summons that follow their leader). */
function needsRoll(c) {
  return !c.lair && !c.reserve && !(c.followLeader && c.leader);
}

/** The creatures a member rolls for: the DM rolls for every enemy. */
function rollsOf(room, member) {
  if (!member) return [];
  return room.combatants.filter((c) => needsRoll(c) && (member.role === 'dm' ? c.type === 'enemy' : c.type !== 'enemy' && c.owner === member.id));
}

/**
 * Who enters initiative, in order: the DM always first, then players in the
 * order they acted in the last combat (join order the first time).
 */
function buildRollQueue(room) {
  const members = Object.values(room.members);
  const dm = members.find((m) => m.role === 'dm');
  const last = room.lastOrder || [];
  const rank = (m) => (last.includes(m.id) ? last.indexOf(m.id) : 1e6);
  const players = members
    .filter((m) => m.role === 'player' && rollsOf(room, m).length)
    .sort((a, b) => rank(a) - rank(b) || a.joinedAt - b.joinedAt);
  return [...(dm && rollsOf(room, dm).length ? [dm.id] : []), ...players.map((m) => m.id)];
}

function joinRollQueue(room, member) {
  if (room.combat.phase !== 'rolling' || member.role === 'screen') return;
  if (!room.combat.queue.includes(member.id)) room.combat.queue.push(member.id);
}

/** Drop everyone at the front of the queue who has entered all their rolls; start the fight when done. */
function advanceRollQueue(room) {
  const q = room.combat.queue;
  let moved = false;
  while (q.length) {
    const m = memberById(room, q[0]);
    if (m && rollsOf(room, m).some((c) => c.initRoll == null)) break;
    q.shift();
    moved = true;
  }
  if (moved) room.combat.seq += 1; // wakes up the next person
  if (!q.length) beginCombat(room);
}

function beginCombat(room) {
  room.combat.phase = null;
  room.combat.queue = [];
  room.combat.active = true;
  room.combat.round = 1;
  room.combat.cursor = null;
  // remember the players' order for the next initiative round
  const order = [];
  for (const c of sortedCombatants(room)) {
    if (c.type !== 'enemy' && c.owner && !order.includes(c.owner)) order.push(c.owner);
  }
  room.lastOrder = order;
  addLog(room, '⚔️ Combat started! — Round 1 —');
  advance(room, +1);
}

/**
 * Start combat. With `roll` (what the app does), everyone first enters their
 * initiative roll, one person at a time; without it, the current
 * initiative values are used straight away.
 */
function startCombat(room, clientId, { roll = false } = {}) {
  const member = getMember(room, clientId);
  requireDm(member);
  const list = eligible(room);
  if (list.length === 0) throw new GameError('Add some creatures first.');
  if (!roll) {
    beginCombat(room);
    touch(room);
    return;
  }
  for (const c of room.combatants) {
    if (needsRoll(c)) { c.initRoll = null; c.initiative = null; }
  }
  room.combat.active = false;
  room.combat.turnId = null;
  room.combat.round = 0;
  room.combat.phase = 'rolling';
  room.combat.queue = buildRollQueue(room);
  room.combat.seq += 1;
  addLog(room, '🎲 Roll for initiative! The DM goes first.');
  advanceRollQueue(room);
  touch(room);
}

/** Enter initiative rolls: [{ id, roll }]. The total is roll + initiative bonus. */
function setInitiative(room, clientId, { rolls } = {}) {
  const member = getMember(room, clientId);
  if (member.role === 'screen') throw new GameError('The table screen only displays the fight.');
  if (!Array.isArray(rolls) || !rolls.length) throw new GameError('Enter an initiative roll.');
  for (const r of rolls.slice(0, LIMITS.combatants)) {
    const c = findCombatant(room, r && r.id);
    if (!canControl(room, member, c)) throw new GameError('You can only roll for your own creatures.');
    if (!needsRoll(c)) throw new GameError(c.lair ? 'Lair actions always happen on initiative 20.' : `${c.name} acts right after its leader.`);
    const roll = int(r.roll, -99, 9999, null);
    if (roll == null) throw new GameError(`Enter a number for ${c.name}.`);
    c.initRoll = roll;
    c.initiative = roll + (c.initBonus || 0);
  }
  if (room.combat.phase === 'rolling') {
    const front = room.combat.queue[0];
    if (front === member.id) addLog(room, `🎲 ${member.name} rolled initiative.`);
    advanceRollQueue(room);
  }
  touch(room);
}

function d20() {
  return 1 + (randomBytes(1)[0] % 20);
}

/** DM: roll automatically for whoever is holding up the initiative round (e.g. offline). */
function skipRoller(room, clientId) {
  const member = getMember(room, clientId);
  requireDm(member);
  if (room.combat.phase !== 'rolling') throw new GameError('Nobody is rolling initiative.');
  const m = memberById(room, room.combat.queue[0]);
  for (const c of rollsOf(room, m)) {
    if (c.initRoll == null) { c.initRoll = d20(); c.initiative = c.initRoll + (c.initBonus || 0); }
  }
  addLog(room, `🎲 ${m ? m.name : 'Someone'}'s initiative was rolled automatically.`);
  if (room.combat.queue.length) room.combat.queue.shift();
  room.combat.seq += 1;
  advanceRollQueue(room);
  touch(room);
}

function endCombat(room, clientId) {
  const member = getMember(room, clientId);
  requireDm(member);
  room.combat.active = false;
  room.combat.phase = null;
  room.combat.queue = [];
  room.combat.turnId = null;
  room.combat.cursor = null;
  room.combat.round = 0;
  room.combat.seq += 1;
  addLog(room, '🏳️ Combat ended.');
  touch(room);
}

/** DM, or the player whose creature is acting, can end the turn. */
function nextTurn(room, clientId) {
  const member = getMember(room, clientId);
  if (!room.combat.active) throw new GameError('Combat has not started.');
  const current = room.combatants.find((c) => c.id === room.combat.turnId);
  if (member.role !== 'dm' && !(current && canControl(room, member, current))) {
    throw new GameError("It's not your turn.");
  }
  if (current) endOfTurn(room, current);
  advance(room, +1);
  touch(room);
}

function prevTurn(room, clientId) {
  const member = getMember(room, clientId);
  requireDm(member);
  if (!room.combat.active) throw new GameError('Combat has not started.');
  advance(room, -1);
  touch(room);
}

function setTurn(room, clientId, id) {
  const member = getMember(room, clientId);
  requireDm(member);
  if (!room.combat.active) throw new GameError('Combat has not started.');
  const c = findCombatant(room, id);
  if (c.hidden) throw new GameError('Reveal this creature first.');
  setCurrent(room, c);
  touch(room);
}

/** Conditions with a duration lose a round when their creature's turn ends. */
function endOfTurn(room, c) {
  if (!c.conditions || !c.conditions.length) return;
  c.conditions = c.conditions.filter((k) => {
    if (k.rounds == null) return true;
    k.rounds -= 1;
    if (k.rounds > 0) return true;
    const text = `${k.emoji} ${k.name} wore off ${c.name}.`;
    if (k.secret || c.hidden) addLog(room, '', text);
    else addLog(room, text);
    return false;
  });
}

function conditionLabel(k) {
  return `${k.emoji} ${k.name}${k.level ? ` ${k.level}` : ''}`;
}

/**
 * Add a condition. DM: to anyone. Players: to any creature they can see
 * (their spells hit enemies and buff allies). Re-adding a condition that is
 * already there refreshes its duration; Exhaustion goes up one level.
 */
function addCondition(room, clientId, { id, condition } = {}) {
  const member = getMember(room, clientId);
  if (member.role === 'screen') throw new GameError('The table screen only displays the fight.');
  const c = findCombatant(room, id);
  const isDm = member.role === 'dm';
  if (!isDm && c.hidden) throw new GameError('That creature no longer exists.');
  const k = cleanCondition(condition, isDm);
  if (!c.conditions) c.conditions = [];
  const say = (text) => (k.secret || c.hidden ? addLog(room, '', text) : addLog(room, text));

  const existing = k.key ? c.conditions.find((x) => x.key === k.key) : c.conditions.find((x) => x.name.toLowerCase() === k.name.toLowerCase());
  if (existing) {
    const preset = CONDITION_PRESETS.find((p) => p.key === existing.key);
    if (preset && preset.levels) {
      existing.level = Math.min(preset.levels, (existing.level || 1) + 1);
      say(`${conditionLabel(existing)}: ${c.name} (by ${member.name}).`);
    } else {
      existing.rounds = k.rounds;
      say(`${conditionLabel(existing)} renewed on ${c.name}${k.rounds ? ` (${k.rounds} rounds)` : ''}.`);
    }
    touch(room);
    return existing;
  }
  if (c.conditions.length >= LIMITS.conditions) throw new GameError('Too many conditions on this creature.');
  const added = { id: randomId(4), ...k, by: member.id };
  c.conditions.push(added);
  say(`${conditionLabel(added)}: ${c.name}${k.rounds ? ` for ${k.rounds} round${k.rounds > 1 ? 's' : ''}` : ''} (by ${member.name}).`);
  touch(room);
  return added;
}

function findCondition(c, condId) {
  const k = (c.conditions || []).find((x) => x.id === condId);
  if (!k) throw new GameError('That condition is already gone.');
  return k;
}

/** DM: any. Players: conditions they added, or any on their own creatures. */
function canRemoveCondition(member, c, k) {
  if (member.role === 'dm') return true;
  if (k.secret) return false;
  return k.by === member.id || (c.type !== 'enemy' && c.owner === member.id);
}

function removeCondition(room, clientId, { id, condId } = {}) {
  const member = getMember(room, clientId);
  const c = findCombatant(room, id);
  const k = findCondition(c, condId);
  if (!canRemoveCondition(member, c, k)) throw new GameError('Only the DM or whoever added it can remove this condition.');
  c.conditions = c.conditions.filter((x) => x.id !== condId);
  const text = `${c.name} is no longer ${k.name}${k.level ? ` ${k.level}` : ''}.`;
  if (k.secret || c.hidden) addLog(room, '', text);
  else addLog(room, text);
  touch(room);
}

/** Change a level-based condition (Exhaustion 1–6); reaching 0 removes it. */
function conditionLevel(room, clientId, { id, condId, delta } = {}) {
  const member = getMember(room, clientId);
  const c = findCombatant(room, id);
  const k = findCondition(c, condId);
  const preset = CONDITION_PRESETS.find((p) => p.key === k.key);
  if (!preset || !preset.levels) throw new GameError('This condition has no levels.');
  const d = int(delta, -1, 1, 0);
  if (d > 0) return addCondition(room, clientId, { id, condition: { preset: k.key } });
  if (!canRemoveCondition(member, c, k)) throw new GameError('Only the DM or whoever added it can change this condition.');
  if ((k.level || 1) <= 1) return removeCondition(room, clientId, { id, condId });
  k.level -= 1;
  addLog(room, `${conditionLabel(k)}: ${c.name}.`);
  touch(room);
  return k;
}

/** Change a bar stat by `delta`, or set it to `value`. Owner or DM. */
function adjustStat(room, clientId, { id, index, delta, value } = {}) {
  const member = getMember(room, clientId);
  const c = findCombatant(room, id);
  if (!canControl(room, member, c)) throw new GameError('You cannot change this creature.');
  const s = c.stats[int(index, 0, LIMITS.stats, -1)];
  if (!s || !isBar(s)) throw new GameError('That bar no longer exists.');
  const next = isBlank(value) ? s.value + int(delta, -BIG, BIG, 0) : int(value, 0, s.max, s.value);
  s.value = Math.min(s.max, Math.max(0, next));
  touch(room);
  return s;
}

/* ------------------------------------------------------------------ */
/* Shared map + DM pen                                                 */
/* ------------------------------------------------------------------ */

const MAP_COLORS = ['red', 'yellow', 'white', 'cyan', 'green', 'black'];
const MAP_LIMITS = { url: 2000, strokes: 200, points: 400 };

function requireMapper(member) {
  if (member.role !== 'dm' && member.role !== 'screen') throw new GameError('Only the DM (or the table display) can change the map.');
}

/** Show a website or an image as the map (empty url = no map). */
function setMap(room, clientId, { url, kind } = {}) {
  const member = getMember(room, clientId);
  requireMapper(member);
  const u = str(url, MAP_LIMITS.url);
  if (u && !/^https?:\/\//i.test(u)) throw new GameError('The map link must start with http:// or https://');
  const isImage = kind === 'image' || (kind !== 'page' && /\.(png|jpe?g|gif|webp|svg|avif)(\?|#|$)/i.test(u));
  if (!room.map) room.map = { url: '', kind: 'page', strokes: [] };
  room.map.url = u;
  room.map.kind = isImage ? 'image' : 'page';
  room.map.strokes = [];
  addLog(room, u ? `🗺️ ${member.name} shared a map.` : `🗺️ ${member.name} removed the map.`);
  touch(room);
}

/** One pen stroke; points are [x, y] in 0..1 of the map box. */
function addStroke(room, clientId, { color, width, points } = {}) {
  const member = getMember(room, clientId);
  requireMapper(member);
  if (!room.map || !room.map.url) throw new GameError('Share a map first.');
  if (!Array.isArray(points)) throw new GameError('Invalid drawing.');
  const clean = [];
  for (const p of points.slice(0, MAP_LIMITS.points)) {
    if (!Array.isArray(p)) continue;
    const x = Number(p[0]);
    const y = Number(p[1]);
    if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
    clean.push([Math.round(Math.min(1, Math.max(0, x)) * 1e4) / 1e4, Math.round(Math.min(1, Math.max(0, y)) * 1e4) / 1e4]);
  }
  if (clean.length < 1) throw new GameError('Invalid drawing.');
  room.map.strokes.push({ id: randomId(4), color: MAP_COLORS.includes(color) ? color : 'red', width: int(width, 1, 3, 2), points: clean });
  if (room.map.strokes.length > MAP_LIMITS.strokes) room.map.strokes.splice(0, room.map.strokes.length - MAP_LIMITS.strokes);
  touch(room);
}

function undoStroke(room, clientId) {
  const member = getMember(room, clientId);
  requireMapper(member);
  if (room.map) room.map.strokes.pop();
  touch(room);
}

function clearStrokes(room, clientId) {
  const member = getMember(room, clientId);
  requireMapper(member);
  if (room.map) room.map.strokes = [];
  touch(room);
}

function updateSettings(room, clientId, settings = {}) {
  const member = getMember(room, clientId);
  requireDm(member);
  if (settings.revealEnemies !== undefined) room.settings.revealEnemies = Boolean(settings.revealEnemies);
  touch(room);
}

/* ------------------------------------------------------------------ */
/* Per-client view                                                     */
/* ------------------------------------------------------------------ */

function hpStatus(c) {
  if (c.lair) return 'Lair';
  if (c.hp <= 0) return 'Defeated';
  const pct = c.hp / c.hpMax;
  if (pct >= 1) return 'Unharmed';
  if (pct > 0.5) return 'Injured';
  if (pct > 0.25) return 'Bloodied';
  return 'Near death';
}

/**
 * Build the state a given client is allowed to see. Secret client ids and
 * the DM key never leave the server except the DM key for the DM.
 */
const ROLE_ORDER = { dm: 0, screen: 1, player: 2 };

function viewFor(room, clientId, isOnline = () => false) {
  const me = room.members[clientId];
  if (!me) return null;
  const isDm = me.role === 'dm';
  const reveal = isDm || room.settings.revealEnemies;
  const ownerName = new Map(Object.values(room.members).map((m) => [m.id, m.name]));

  const current = room.combat.active ? room.combatants.find((c) => c.id === room.combat.turnId) : null;

  const byIdAll = new Map(room.combatants.map((c) => [c.id, c]));
  const combatants = sortedCombatants(room)
    .filter((c) => isDm || !c.hidden)
    .map((c) => {
      const secret = c.type === 'enemy' && !reveal;
      return {
        id: c.id,
        type: c.type,
        owner: c.owner,
        ownerName: c.owner ? ownerName.get(c.owner) || '?' : 'DM',
        name: c.name,
        cls: c.cls,
        level: c.level,
        initiative: shownInitiative(room, c),
        initRoll: c.initRoll ?? null,
        needsRoll: needsRoll(c),
        initBonus: secret ? null : c.initBonus || 0,
        boss: Boolean(c.boss),
        lair: Boolean(c.lair),
        leader: c.leader && (isDm || !(byIdAll.get(c.leader) || {}).hidden) ? c.leader : null,
        leaderName: c.leader && byIdAll.get(c.leader) && (isDm || !byIdAll.get(c.leader).hidden) ? byIdAll.get(c.leader).name : null,
        onLeaderDeath: isDm ? c.onLeaderDeath || 'dies' : undefined,
        followLeader: Boolean(c.followLeader),
        conditions: (c.conditions || [])
          .filter((k) => isDm || !k.secret)
          .map((k) => ({ ...k, canRemove: canRemoveCondition(me, c, k) })),
        hidden: Boolean(c.hidden),
        reserve: Boolean(c.reserve),
        hp: secret ? null : c.hp,
        hpMax: secret ? null : c.hpMax,
        hpPct: Math.round((c.hp / c.hpMax) * 100),
        status: hpStatus(c),
        ac: secret ? null : c.ac,
        stats: secret ? [] : c.stats,
        mine: canControl(room, me, c) && (c.type !== 'enemy' || isDm),
        defeated: c.hp <= 0,
      };
    });

  const yourTurn = Boolean(current && (current.type === 'enemy' ? isDm : current.owner === me.id));

  return {
    code: room.code,
    you: { id: me.id, name: me.name, role: me.role },
    dmKey: isDm || (me.role === 'screen' && me.creator) ? room.dmKey : undefined,
    members: Object.entries(room.members)
      .map(([cid, m]) => ({ id: m.id, name: m.name, role: m.role, online: isOnline(cid) }))
      .sort((a, b) => ROLE_ORDER[a.role] - ROLE_ORDER[b.role] || a.name.localeCompare(b.name)),
    combatants,
    combat: {
      active: room.combat.active,
      round: room.combat.round,
      turnId: current && (isDm || !current.hidden) ? current.id : null,
      seq: room.combat.seq,
      phase: room.combat.phase || null,
      rollers: (room.combat.queue || []).map((id) => {
        const m = memberById(room, id);
        return { id, name: m ? m.name : '?', role: m ? m.role : 'player' };
      }),
    },
    yourRoll: room.combat.phase === 'rolling' && (room.combat.queue || [])[0] === me.id,
    map: room.map
      ? { url: room.map.url, kind: room.map.kind, strokes: room.map.strokes }
      : { url: '', kind: 'page', strokes: [] },
    canMap: me.role === 'dm' || me.role === 'screen',
    yourTurn,
    settings: { ...room.settings },
    log: room.log
      .map((l) => ({ t: l.t, text: isDm && l.dm ? l.dm : l.text }))
      .filter((l) => l.text)
      .slice(-40),
  };
}

return {
  GameError,
  LIMITS,
  normalizeCode,
  createRoom,
  joinRoom,
  getMember,
  memberById,
  dmMember,
  saveCombatant,
  removeCombatant,
  changeHp,
  startCombat,
  endCombat,
  nextTurn,
  prevTurn,
  setTurn,
  updateSettings,
  adjustStat,
  addCondition,
  removeCondition,
  setInitiative,
  skipRoller,
  setReserve,
  setMap,
  addStroke,
  undoStroke,
  clearStrokes,
  MAP_COLORS,
  conditionLevel,
  BAR_COLORS,
  TINTS,
  CONDITION_PRESETS,
  sortedCombatants,
  eligible,
  viewFor,
  hpStatus,
};
});
